function save(change){if(readError){notify('Não foi possível carregar seus dados. Atualize a página e tente novamente.',true);return false;}try{const next=JSON.parse(JSON.stringify(state));if(!L.validState(next))throw Error();const result=change(next);if(typeof result==='string'){notify(result,true);return false;}next.revision++;if(!L.validState(next))throw Error();localStorage.setItem(KEY,JSON.stringify(next));state=next;return true;}catch{notify('Não foi possível salvar. Verifique se o armazenamento do navegador está disponível.',true);return false;}}
