save=function(change){if(persistPending){notify('Aguarde a conclusão do registro anterior.',true);return false;}if(!window.EbenFirestore?.isReady){notify('Aguarde o carregamento da sua conta antes de salvar.',true);return false;}const previous=JSON.parse(JSON.stringify(state));const ok=saveLocal(change);const submitButtons=Array.from(document.querySelectorAll('#checkoutForm button, #homeBookingForm button, #appDialog button, #blockForm button'));if(ok)submitButtons.forEach(button=>button.disabled=true);window.EbenLastPersist=Promise.resolve(ok);if(ok&&window.EbenFirestore)window.EbenLastPersist=(persistPending=true,window.EbenFirestore.persist(state)).then(()=>true).catch(error=>{console.error('Falha ao salvar no Firestore:',error);notify('Não foi possível salvar suas alterações. Verifique sua conexão e tente novamente.',true);window.EbenLivingSetCloudState(previous);return false;}).finally(()=>{persistPending=false;submitButtons.forEach(button=>button.disabled=false);});return ok;};
window.EbenLivingSetCloudState=function(remote){if(!L.validState(remote))return;state=remote;readError=false;try{localStorage.setItem(KEY,JSON.stringify(state));}catch{}home();admin();trips();if(!persistPending){if(!$('bookingForm')&&!$('homeBookingForm'))detail();if(!$('checkoutForm'))checkout();updateQuote();}window.renderManagement?.();};
function property(id=params.get('id')||params.get('property')){return state.properties.find(p=>p.id===id);}
function empty(title,text,href='/',label='Explorar acomodações'){return `<div class="empty-state"><span aria-hidden="true">⌂</span><h2>${e(title)}</h2><p>${e(text)}</p><a class="btn btn-primary" href="${e(href)}">${e(label)}</a></div>`;}
function favorite(p){const yes=state.favorites.includes(p.id);return `<button class="favorite-button ${yes?'is-saved':''}" data-action="favorite" data-id="${e(p.id)}" aria-pressed="${yes}" aria-label="${yes?'Remover dos':'Adicionar aos'} favoritos: ${e(p.title)}">${yes?'♥':'♡'}</button>`;}
