function managedProperties(plan=adminPlan){if(!plan)return [];const uid=window.EbenFirestore?.uid;if(!uid)return [];return (window.EbenFirestore?.isAdmin?state.properties:state.properties.filter(item=>item.ownerId===uid)).filter(item=>!item.deletedAt&&(!plan||plan==='all'||(item.plan||'flex')===plan));}
