function reservationsTable() {
  if (!$('reservationsRows')) return;
  const term = $('reservationSearch').value.toLowerCase();
  const status = $('reservationStatus').value;
  const list = [...managedReservations()].reverse().filter(reservation =>
    property(reservation.propertyId) && (!status || reservation.status === status) &&
    `${reservation.id} ${reservation.guest} ${property(reservation.propertyId).title}`.toLowerCase().includes(term)
  );
  $('reservationsRows').innerHTML = list.length ? list.map(reservation => {
    const p = property(reservation.propertyId);
    const home = p.plan === 'home';
    const stage = Number(reservation.stage || 0);
    const docs = reservation.documents || {};
    const actions = [];
    if (reservation.status === 'pendente' && stage === 0) {
      actions.push(`<button class="text-button" data-action="confirm" data-id="${e(reservation.id)}">Aprovar primeira fase</button>`);
    }
    if (home && stage === 1) {
      actions.push(docs.identity
        ? `<button class="text-button" data-rental-action="view-document" data-kind="identity" data-id="${e(reservation.id)}">Ver identidade enviada</button><button class="text-button" data-rental-action="identity-review" data-id="${e(reservation.id)}">Aprovar identidade</button>`
        : '<small>Aguardando envio da identidade pelo inquilino.</small>');
    }
    if (home && stage === 2) {
      actions.push(`<label class="field">CPF do inquilino<input data-tenant-cpf="${e(reservation.id)}" inputmode="numeric" maxlength="14" value="${e(reservation.cpf || '')}"></label><button class="text-button" data-rental-action="save-cpf" data-id="${e(reservation.id)}">Salvar CPF</button>`);
    }
    if (home && stage === 3) actions.push('<small>Aguardando contrato assinado pelo inquilino.</small>');
    if (home && stage === 4) {
      if (docs.tenantContract) actions.push(`<button class="text-button" data-rental-action="view-document" data-kind="tenant-contract" data-id="${e(reservation.id)}" data-download="true">Baixar contrato do inquilino</button>`);
      actions.push(`<label class="field">Sua assinatura (PDF ate 5 MB)<input type="file" accept="application/pdf" data-rental-file="host-contract" data-id="${e(reservation.id)}"></label><button class="text-button" data-rental-action="host-contract" data-id="${e(reservation.id)}">Enviar contrato assinado</button>`);
    }
    if (home && stage === 5) actions.push(`<button class="text-button" data-rental-action="keys" data-id="${e(reservation.id)}">Registrar entrega das chaves</button>`);
    if (home && stage >= 6) actions.push('<small>Entrega das chaves registrada</small>');
    if (reservation.status !== 'cancelada') actions.push(`<button class="text-button" data-action="cancel" data-id="${e(reservation.id)}">Cancelar</button>`);
    const termLabel = { '6months': '6 meses', '1year': '1 ano', '2years': '2 anos', '3years': '3 anos', annual: '1 ano', monthly: '1 mes' }[reservation.term] || reservation.term;
    const details = reservation.term ? `Contrato de ${e(termLabel)}` : (reservation.plan === 'mobile' || p.plan === 'mobile') ? `Eben Mobile - ${e(useName(reservation.rentalUse))}` : `${reservation.guests} hospede(s)`;
    return `<tr><td>${e(reservation.id)}</td><td>${e(reservation.guest)}${contactLinks(reservation)}${home && reservation.cpf ? `<small>CPF: ${e(reservation.cpf)}</small>` : ''}</td><td>${e(p.title)}${reservation.plan === 'mobile' ? `<br><small>${e(useName(reservation.rentalUse))}</small>` : ''}</td><td>${date(reservation.checkIn)}<br>${date(reservation.checkOut)}<br><small>${details}</small></td><td>${money(reservation.total)}</td><td>${statusChip(reservation.status)}${home ? `<br><small>Etapa ${stage}/6</small>` : ''}${expiryNote(reservation)}</td><td><div class="table-actions">${actions.join('')}</div></td></tr>`;
  }).join('') : '<tr><td colspan="7" class="table-empty">Nenhuma reserva encontrada para suas acomodações.</td></tr>';
}
function adminCalendar(){if(!$('adminCalendar'))return;const p=managedProperties().find(item=>item.id===$('calendarProperty').value);if(!p){$('adminCalendar').innerHTML='<p class="muted">Cadastre uma acomodação para gerenciar a disponibilidade.</p>';if($('blockedDates'))$('blockedDates').innerHTML='';return;}$('adminCalendar').innerHTML=calendar(p);$('blockedDates').innerHTML=(p.unavailable||[]).filter(d=>d>=L.today()).sort().map(d=>`<button class="block-chip" data-action="unblock" data-id="${e(p.id)}" data-date="${d}" aria-label="Desbloquear ${date(d)}">${date(d)} ×</button>`).join('')||'<p class="small muted">Nenhum bloqueio manual futuro.</p>';}
